const input = $json || {};

const sampleEvents = [
  {
    source: 'InterNations',
    title: 'Dubai International Social Mixer',
    start: '2026-08-07T19:30:00+04:00',
    end: '2026-08-07T22:30:00+04:00',
    location: 'Dubai Marina',
    sourceUrl: 'https://example.com/internations-event',
    estimatedCost: 120,
    currency: 'AED',
    category: 'social',
    description: 'International crowd, social mixer, solo-friendly.'
  },
  {
    source: 'Timeleft',
    title: 'Dinner with New People',
    start: '2026-08-08T20:00:00+04:00',
    end: '2026-08-08T22:30:00+04:00',
    location: 'Downtown Dubai',
    sourceUrl: 'https://example.com/timeleft-event',
    estimatedCost: 180,
    currency: 'AED',
    category: 'dating_social',
    description: 'Small-group dinner with strangers.'
  },
  {
    source: 'Soho Garden',
    title: 'Friday Social Night',
    start: '2026-08-08T22:00:00+04:00',
    end: '2026-08-09T02:00:00+04:00',
    location: 'Dubai',
    sourceUrl: 'https://example.com/soho-event',
    estimatedCost: 250,
    currency: 'AED',
    category: 'nightlife',
    description: 'Nightlife event with strong social atmosphere.'
  },
  {
    source: 'Skyscanner',
    title: 'Weekend Muscat Escape',
    start: '2026-08-09T09:00:00+04:00',
    end: '2026-08-10T21:00:00+04:00',
    location: 'Muscat',
    sourceUrl: 'https://example.com/skyscanner-trip',
    estimatedCost: 850,
    currency: 'AED',
    category: 'travel',
    description: 'Short weekend travel opportunity.'
  }
];

let sourceEvents = [];

if (Array.isArray(input.events)) {
  sourceEvents = input.events;
} else if (Array.isArray(input.sourceEvents)) {
  sourceEvents = input.sourceEvents;
} else if (Array.isArray(input.connectorOutputs)) {
  sourceEvents = input.connectorOutputs.flatMap(connector => {
    if (Array.isArray(connector?.events)) return connector.events;
    if (Array.isArray(connector?.result?.events)) return connector.result.events;
    return [];
  });
} else if (Array.isArray(input.forwardedItems)) {
  sourceEvents = input.forwardedItems;
} else {
  sourceEvents = sampleEvents;
}

return [{
  json: {
    request: input.request || {
      text: 'Bu hafta sonu sosyal, nightlife veya travel fırsatı bul',
      channel: 'manual_test',
      userId: 'savas'
    },
    context: input.context || {
      timezone: 'Asia/Dubai',
      userContext: {
        identity: { name: 'Savaş', language: 'Turkish' },
        locations: {
          home: 'Palm Jumeirah, Dubai',
          work: 'Abu Dhabi'
        },
        goals: {
          social: 'Build a quality international social circle',
          dating: 'Create genuine dating opportunities',
          travel: 'Take more weekend trips'
        },
        preferences: {
          venues: 'Bars, rooftops, lounges, beach clubs, social activities',
          memberships: 'Privilee, InterNations, Meetup'
        }
      },
      derivedContext: {
        calendarLoad: 'low',
        isWeekend: true,
        needsMoreSocial: true,
        needsMoreFitness: true,
        preferredPlanningWindow: {
          start: '17:00',
          end: '23:00'
        }
      },
      userState: {
        energyLevel: 'high',
        mood: 'social',
        budgetAED: 1200,
        maxTravelMinutes: 45
      }
    },
    sourceEvents,
    metadata: input.metadata || {
      correlationId: `social-discovery-${Date.now()}`,
      testMode: true
    }
  }
}];

const input = $json || {};
const events = Array.isArray(input.sourceEvents) ? input.sourceEvents : [];
const context = input.context || {};
const derived = context.derivedContext || context.derived || {};
const userState = context.userState || {};
const metadata = input.metadata || {};

const sourceRegistry = {
  // Tier 1: Dating & Social Life
  'InterNations': { priority: 10, domain: 'dating_social' },
  'Meetup': { priority: 9.5, domain: 'dating_social' },
  'Timeleft': { priority: 9.5, domain: 'dating_social' },
  'Eventbrite': { priority: 9, domain: 'dating_social' },
  'Dubai Calendar': { priority: 8.5, domain: 'dating_social' },
  'Privilee': { priority: 8.5, domain: 'dating_social_fitness' },
  'TimeOut Dubai': { priority: 8.5, domain: 'dating_social_nightlife' },
  "What's On Dubai": { priority: 8.5, domain: 'dating_social_nightlife' },
  'Platinumlist': { priority: 8.5, domain: 'dating_social_nightlife' },
  'Google Events': { priority: 7.5, domain: 'general_events' },
  'Visit Dubai': { priority: 7.5, domain: 'culture_travel' },

  // Tier 2: Nightlife
  'Secret Parties Dubai': { priority: 9, domain: 'nightlife' },
  'Bla Bla Dubai': { priority: 8.5, domain: 'nightlife' },
  'Barasti': { priority: 8, domain: 'nightlife' },
  "McGettigan's": { priority: 8, domain: 'nightlife_social' },
  'Zero Gravity': { priority: 8.5, domain: 'nightlife' },
  'Surf Club Dubai': { priority: 8.5, domain: 'nightlife' },
  'FIVE Palm': { priority: 9, domain: 'nightlife' },
  'Soho Garden': { priority: 9, domain: 'nightlife' },
  'WHITE Beach': { priority: 9, domain: 'nightlife' },

  // Tier 3: Travel
  'Skyscanner': { priority: 9, domain: 'travel' },
  'Booking.com': { priority: 8.5, domain: 'travel' },
  'Airbnb': { priority: 8, domain: 'travel' },
  'FlyDubai Holidays': { priority: 8.5, domain: 'travel' },
  'Etihad Holidays': { priority: 8.5, domain: 'travel' },
  'Wizz Air': { priority: 8, domain: 'travel' },
  'Visit Oman': { priority: 8.5, domain: 'travel' },
  'Visit Abu Dhabi': { priority: 8, domain: 'travel_culture' },

  // Tier 4: Fitness & Wellness
  'ClassPass': { priority: 7.5, domain: 'fitness' },
  'GymNation': { priority: 7, domain: 'fitness' },
  'Warehouse Gym': { priority: 7.5, domain: 'fitness' },
  "Barry's": { priority: 7.5, domain: 'fitness' },
  'F45': { priority: 7.5, domain: 'fitness' },
  'Fitness First': { priority: 7, domain: 'fitness' },

  // Tier 5: Career & Networking
  'LinkedIn Events': { priority: 7.5, domain: 'career_networking' },
  'Microsoft Reactor': { priority: 7, domain: 'career_networking' },
  'AWS User Groups': { priority: 7, domain: 'career_networking' },
  'OWASP UAE': { priority: 7.5, domain: 'career_networking' },
  'ISACA UAE': { priority: 7.5, domain: 'career_networking' },
  'ISC2 UAE': { priority: 7.5, domain: 'career_networking' },
  'GDG Dubai': { priority: 7, domain: 'career_networking' },
  'Hub71': { priority: 7.5, domain: 'startup_networking' },
  'in5': { priority: 7.5, domain: 'startup_networking' },
  'DIFC Innovation Hub': { priority: 7.5, domain: 'startup_networking' },
  'Astrolabs': { priority: 7.5, domain: 'startup_networking' },
  'Dubai AI Campus': { priority: 7.5, domain: 'startup_networking' },
  'AREA 2071': { priority: 7.5, domain: 'startup_networking' },

  // Tier 6: Culture & Lifestyle
  'Dubai Opera': { priority: 7, domain: 'culture' },
  'Coca-Cola Arena': { priority: 7, domain: 'culture_nightlife' },
  'The Agenda Dubai': { priority: 7, domain: 'culture_networking' },
  'Dubai World Trade Centre': { priority: 7, domain: 'career_culture' },
  'Expo City Dubai': { priority: 7, domain: 'culture' },
  'Museum of the Future': { priority: 6.5, domain: 'culture' },
  'Art Dubai': { priority: 7, domain: 'culture' },
  'Louvre Abu Dhabi': { priority: 6.5, domain: 'culture' },
  'Comedy Clubs': { priority: 7.5, domain: 'culture_social' },
  'Jazz Clubs': { priority: 7.5, domain: 'culture_social' },

  // Forwarded / social media
  'WhatsApp Forward': { priority: 7, domain: 'forwarded' },
  'Telegram Forward': { priority: 7, domain: 'forwarded' },
  'Instagram Link': { priority: 7, domain: 'forwarded_social' },
  'Facebook Events': { priority: 7, domain: 'social_events' },
  'Unknown': { priority: 4, domain: 'unknown' }
};

const normalizeText = value =>
  String(value || '').trim().toLocaleLowerCase('tr-TR');

const clamp10 = value => Math.max(0, Math.min(10, Number(value ?? 0)));

const getCategory = event => {
  const text = normalizeText(
    `${event.category || ''} ${event.title || ''} ${event.description || ''} ${event.source || ''}`
  );

  if (text.includes('travel') || text.includes('trip') || text.includes('flight') || text.includes('hotel')) return 'travel';
  if (text.includes('fitness') || text.includes('gym') || text.includes('boxing') || text.includes('padel') || text.includes('tennis')) return 'fitness';
  if (text.includes('dating') || text.includes('singles') || text.includes('speed dating') || text.includes('timeleft')) return 'dating';
  if (text.includes('night') || text.includes('dj') || text.includes('party') || text.includes('rooftop') || text.includes('club')) return 'nightlife';
  if (text.includes('career') || text.includes('cyber') || text.includes('aws') || text.includes('owasp') || text.includes('isaca') || text.includes('isc2')) return 'career';
  if (text.includes('opera') || text.includes('jazz') || text.includes('comedy') || text.includes('museum') || text.includes('art')) return 'culture';
  if (text.includes('network') || text.includes('mixer') || text.includes('social') || text.includes('expat') || text.includes('community')) return 'social';
  return event.category || 'social';
};

const parseDate = value => {
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d;
};

const preferredStart = (() => {
  const start = derived.preferredPlanningWindow?.start || '18:00';
  const [h, m] = start.split(':').map(Number);
  return h * 60 + m;
})();

const recommendations = [];
const rejected = [];
const duplicateLogs = [];

for (let i = 0; i < events.length; i++) {
  const event = events[i] || {};
  const title = String(event.title || event.name || event.eventTitle || '').trim();
  if (!title) {
    rejected.push({ index: i, reason: 'missing_title', event });
    continue;
  }

  const startRaw = event.start || event.startTime || event.dateTime || event.date || null;
  const startDate = startRaw ? parseDate(startRaw) : null;
  if (!startDate) {
    rejected.push({ index: i, title, reason: 'missing_or_invalid_start', event });
    continue;
  }

  const endRaw = event.end || event.endTime || null;
  const endDate = endRaw ? parseDate(endRaw) : null;

  const source = String(event.source || event.platform || 'Unknown').trim();
  const registry = sourceRegistry[source] || sourceRegistry.Unknown;
  const location = String(event.location || event.venue || event.city || '').trim();
  const sourceUrl = event.sourceUrl || event.url || event.link || null;
  const description = String(event.description || event.text || '').trim();
  const category = getCategory(event);

  const locationText = normalizeText(location);
  const allowedRegion =
    category === 'travel' ||
    locationText.includes('dubai') ||
    locationText.includes('palm') ||
    locationText.includes('marina') ||
    locationText.includes('jbr') ||
    locationText.includes('difc') ||
    locationText.includes('downtown') ||
    locationText.includes('abu dhabi') ||
    locationText.includes('muscat') ||
    !location;

  if (!allowedRegion) {
    rejected.push({ index: i, title, reason: 'outside_preferred_region', location });
    continue;
  }

  const timeStr = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Asia/Dubai',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  }).format(startDate);

  const [hour, minute] = timeStr.split(':').map(Number);
  const startMinutes = hour * 60 + minute;

  const sourcePriority = registry.priority;
  const datingPotential =
    category === 'dating' ? 10 :
    category === 'social' ? 9 :
    category === 'nightlife' ? 9 :
    category === 'travel' ? 6 : 4;

  const socialQuality =
    category === 'social' ? 10 :
    category === 'dating' ? 9 :
    category === 'nightlife' ? 8 :
    category === 'travel' ? 7 : 6;

  const audienceFit =
    source === 'InterNations' ? 10 :
    source === 'Meetup' ? 9 :
    source === 'Timeleft' ? 9 :
    source === 'Privilee' ? 8 :
    source === 'LinkedIn Events' ? 8 :
    7;

  const soloFriendly =
    ['InterNations','Meetup','Timeleft'].includes(source) ? 9 :
    category === 'social' ? 8 :
    category === 'nightlife' ? 7 :
    category === 'travel' ? 7 : 6;

  const travelConvenience =
    category === 'travel' ? 5 :
    locationText.includes('palm') ? 10 :
    locationText.includes('marina') || locationText.includes('jbr') ? 9 :
    locationText.includes('difc') || locationText.includes('downtown') ? 7 :
    locationText.includes('abu dhabi') ? 4 : 6;

  const calendarCompatibility = startMinutes >= preferredStart ? 9 : 6;

  const budget = Number(userState.budgetAED);
  const cost = Number(event.estimatedCost ?? event.cost ?? event.price ?? 0);

  const valueForMoney =
    Number.isFinite(budget) && Number.isFinite(cost)
      ? cost <= budget ? 8 : 4
      : 7;

  const funNovelty =
    category === 'travel' ? 10 :
    category === 'nightlife' ? 9 :
    category === 'dating' ? 9 :
    category === 'social' ? 8 :
    category === 'culture' ? 8 : 6;

  const networkingValue =
    category === 'career' ? 10 :
    source === 'InterNations' ? 9 :
    source === 'LinkedIn Events' ? 10 :
    source === 'Meetup' ? 8 :
    category === 'social' ? 8 : 5;

  const confidence = sourceUrl ? 0.9 : description ? 0.75 : 0.6;

  recommendations.push({
    id: event.id || `${source.replace(/\s+/g,'-').toLowerCase()}-${Date.now()}-${i+1}`,
    title,
    category,
    source,
    sourceDomain: registry.domain,
    sourcePriority,
    sourceUrl,
    start: startDate.toISOString(),
    end: endDate ? endDate.toISOString() : null,
    location,
    estimatedCost: Number.isFinite(cost) ? cost : null,
    currency: event.currency || 'AED',
    confidence,
    reason: description || `${source} opportunity with ${category} potential.`,
    rawScores: {
      calendarCompatibility: clamp10(calendarCompatibility),
      travelConvenience: clamp10(travelConvenience),
      socialQuality: clamp10(socialQuality),
      audienceFit: clamp10(audienceFit),
      fitnessValue: category === 'fitness' ? 10 : 1,
      growthValue: ['social','dating','career','travel'].includes(category) ? 8 : 6,
      networkingValue: clamp10(networkingValue),
      organicConnectionPotential: clamp10(datingPotential),
      funNovelty: clamp10(funNovelty),
      valueForMoney: clamp10(valueForMoney),
      soloFriendly: clamp10(soloFriendly),
      sourcePriority: clamp10(sourcePriority),
      travelValue: category === 'travel' ? 10 : 1,
      nightlifeValue: category === 'nightlife' ? 10 : 1
    },
    metadata: {
      originalSourceEvent: event,
      discoveredAt: new Date().toISOString()
    }
  });
}

const keyFor = item => [
  normalizeText(item.title),
  normalizeText(item.location),
  String(item.start).slice(0,16)
].join('|');

const map = new Map();

for (const item of recommendations) {
  const key = keyFor(item);
  const current = map.get(key);

  if (!current) {
    map.set(key, item);
    continue;
  }

  const currentStrength = current.sourcePriority + current.confidence * 10;
  const newStrength = item.sourcePriority + item.confidence * 10;

  if (newStrength > currentStrength) {
    map.set(key, item);
    duplicateLogs.push({
      level: 'info',
      message: 'Duplicate replaced by higher-priority source.',
      details: {
        title: item.title,
        retainedSource: item.source,
        removedSource: current.source
      }
    });
  } else {
    duplicateLogs.push({
      level: 'info',
      message: 'Duplicate removed.',
      details: {
        title: item.title,
        retainedSource: current.source,
        removedSource: item.source
      }
    });
  }
}

const unique = [...map.values()].sort((a,b) => {
  if (b.sourcePriority !== a.sourcePriority) return b.sourcePriority - a.sourcePriority;
  return b.confidence - a.confidence;
});

return [{
  json: {
    success: true,
    result: {
      agent: 'social_discovery',
      summary: `Found ${unique.length} unique opportunities from ${events.length} source items.`,
      sourceRegistry,
      recommendations: unique.slice(0, 50),
      rejectedEvents: rejected
    },
    memoryUpdates: unique.slice(0,50).map(item => ({
      type: 'discovered_event',
      operation: 'append',
      payload: {
        id: item.id,
        title: item.title,
        category: item.category,
        source: item.source,
        start: item.start,
        location: item.location,
        status: 'discovered',
        discoveredAt: item.metadata.discoveredAt
      }
    })),
    approvalRequests: [],
    logs: [
      {
        timestamp: new Date().toISOString(),
        workflow: 'Concierge OS - Social Discovery Agent',
        level: rejected.length ? 'warning' : 'info',
        correlationId: metadata.correlationId || '',
        message: `Normalized ${unique.length} opportunities.`,
        details: {
          sourceItemCount: events.length,
          recommendationCount: unique.length,
          rejectedCount: rejected.length,
          duplicateCount: duplicateLogs.length
        }
      },
      ...duplicateLogs.map(log => ({
        timestamp: new Date().toISOString(),
        workflow: 'Concierge OS - Social Discovery Agent',
        correlationId: metadata.correlationId || '',
        ...log
      }))
    ],
    nextAction: {
      type: 'rank_recommendations',
      targetWorkflow: 'Concierge OS - Recommendation Engine'
    },
    error: null
  }
}];
